/**
 * ErrorRecoveryDialog - 智能错误恢复对话框 (v7.0)
 *
 * 功能特性：
 * 1. 根据错误类型显示差异化的恢复策略和 UI
 * 2. 支持自动重试机制（可配置重试次数）
 * 3. 提供用户友好的错误提示和操作建议
 * 4. 支持倒计时器（限流错误）
 * 5. 可折叠的技术详情面板
 *
 * 错误类型支持：
 * - NetworkTimeout: 网络超时，自动重试3次
 * - Unauthorized: 401未授权，跳转登录
 * - RateLimited: 429限流，倒计时+禁用发送
 * - ServerError: 500服务器错误，指数退避重试
 * - StreamInterrupted: 流式中断，重连选项
 * - Unknown: 未知错误，通用恢复策略
 *
 * @version 7.0.0
 * @lastUpdated 2026-05-11
 */

import React, { useState, useEffect, useCallback, useMemo } from 'react'
import {
  AlertTriangle,
  WifiOff,
  Lock,
  Timer,
  ServerCrash,
  Unplug,
  RefreshCw,
  X,
  LogIn,
  Bug,
  Lightbulb,
} from 'lucide-react'
import { Button } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

export enum ErrorType {
  NetworkTimeout = 'network_timeout',
  NetworkUnreachable = 'network_unreachable',
  Unauthorized = 'unauthorized',
  Forbidden = 'forbidden',
  RateLimited = 'rate_limited',
  ServerError = 'server_error',
  StreamInterrupted = 'stream_interrupted',
  Unknown = 'unknown',
}

interface ClassifiedError {
  type: ErrorType
  originalError: Error
  userMessage: string
  suggestion: string
  canAutoRecover: boolean
  retryAfter?: number
  countdown?: number
}

export interface ErrorRecoveryDialogProps {
  error: Error | null
  errorType?: ErrorType
  onRetry?: () => Promise<void>
  onDismiss?: () => void
  onLogin?: () => void
  autoRetryCount?: number
  showDetails?: boolean
  className?: string
}

