/**
 * SessionHistory - 会话历史列表组件
 *
 * 职责：
 * - 显示用户的对话会话列表
 * - 支持搜索和筛选会话
 * - 支持打开、删除会话操作
 * - 显示会话基本信息（标题、消息数量、最后更新时间）
 * - Material Design 3 风格的卡片设计
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-20
 */

import React, { useState, useEffect, useCallback } from 'react';
import { MessageSquare, Search, Trash2, Plus, Clock, FileText, ChevronRight, FolderOpen } from 'lucide-react';
import { clsx } from 'clsx';
import type { ChatSession } from '@/api/chat';


import { logger } from '@/utils/safeLogger';
// ===== 类型定义 =====

export interface SessionHistoryProps {
  sessions: ChatSession[];
  currentSessionId: string | null;
  onOpenSession: (sessionId: number) => void;
  onCreateSession: (title: string) => void;
  onDeleteSession: (sessionId: number) => void;
  onLoadSessions: () => void;
}

// ===== 辅助函数 =====

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diff = now.getTime() - date.getTime();
  const days = Math.floor(diff / (1000 * 60 * 60 * 24));

  if (days === 0) {
    return '今天';
  } else if (days === 1) {
    return '昨天';
  } else if (days < 7) {
    return `${days}天前`;
  } else if (days < 30) {
    return `${Math.floor(days / 7)}周前`;
  } else if (days < 365) {
    return `${Math.floor(days / 30)}个月前`;
  } else {
    return `${Math.floor(days / 365)}年前`;
  }
}

function formatTime(dateString: string): string {
  return new Date(dateString).toLocaleTimeString('zh-CN', {
    hour: '2-digit',
    minute: '2-digit',
  });
}

// ===== 会话卡片组件 =====

const SessionCard: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onDelete: () => void;
}> = ({ session, isActive, onClick, onDelete }) => {
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowDeleteConfirm(true);
  };

  const handleConfirmDelete = () => {
    onDelete();
    setShowDeleteConfirm(false);
  };

  const handleCancelDelete = () => {
    setShowDeleteConfirm(false);
  };

  return (
    <div
      className={clsx(
        'group relative p-4 rounded-xl cursor-pointer transition-all duration-200',
        'border-2',
        isActive
          ? 'border-primary-500 bg-primary-50/30 dark:bg-primary-300/20'
          : 'border-transparent bg-neutral-50/50 dark:bg-neutral-800/50 hover:border-neutral-200 dark:hover:border-neutral-700',
        'hover:shadow-md',
        'animate-fade-in',
      )}
       role="button" tabIndex={0} onClick={onClick}
    >
      {/* 内容区域 */}
      <div className="flex items-start gap-3">
        {/* 图标 */}
        <div
          className={clsx(
            'w-10 h-10 rounded-lg flex items-center justify-center shrink-0',
            isActive ? 'bg-primary-container text-primary-main' : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-400',
          )}
        >
          <MessageSquare className="w-5 h-5" />
        </div>

        {/* 信息区域 */}
        <div className="flex-1 min-w-0">
          <h3
            className={clsx(
              'text-sm font-medium truncate',
              isActive ? 'text-primary-700 dark:text-primary-700' : 'text-neutral-800 dark:text-neutral-200',
            )}
          >
            {session.title || '未命名会话'}
          </h3>

          <div className="flex items-center gap-3 mt-1">
            <span className="flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <FileText className="w-3 h-3" />
              {session.message_count} 条消息
            </span>
            <span className="flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <Clock className="w-3 h-3" />
              {formatDate(session.updated_at)} {formatTime(session.updated_at)}
            </span>
          </div>

          {/* 标签显示 */}
          {session.tags && session.tags.length > 0 && (
            <div className="flex flex-wrap gap-1 mt-2">
              {session.tags.slice(0, 3).map((tag: any, index: any) => (
                <span
                  key={index}
                  className="px-2 py-0.5 text-xs bg-neutral-100 dark:bg-neutral-700 rounded-full text-neutral-500"
                >
                  {tag}
                </span>
              ))}
              {session.tags.length > 3 && (
                <span className="px-2 py-0.5 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+{session.tags.length - 3}</span>
              )}
            </div>
          )}
        </div>

        {/* 箭头和删除按钮 */}
        <div className="flex items-center gap-1">
          <button
            onClick={handleDeleteClick}
            className={clsx(
              'p-2 rounded-lg opacity-0 group-hover:opacity-100',
              'hover:bg-error-50 dark:hover:bg-error-900/30',
              'transition-all duration-200',
            )}
            title="删除会话"
            aria-label="删除此会话"
          >
            <Trash2 className="w-4 h-4 text-error-500" />
          </button>
          <ChevronRight
            className={clsx(
              'w-4 h-4 transition-transform duration-200',
              isActive ? 'text-primary-500' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] group-hover:text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]',
            )}
          />
        </div>
      </div>

      {/* 删除确认弹窗 */}
      {showDeleteConfirm && (
        <>
          <div className="fixed inset-0 z-50"  role="button" tabIndex={0} onClick={handleCancelDelete} />
          <div className="absolute z-50 right-0 top-full mt-2 bg-white dark:bg-neutral-800 rounded-xl shadow-lg border border-neutral-200 dark:border-neutral-700 p-3 min-w-[200px]">
            <p className="text-sm text-neutral-700 dark:text-neutral-300 mb-3">确定要删除此会话吗？</p>
            <div className="flex gap-2">
              <button
                onClick={handleCancelDelete}
                className="flex-1 px-3 py-1.5 text-xs text-neutral-600 dark:text-neutral-400 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
              >
                取消
              </button>
              <button
                onClick={handleConfirmDelete}
                className="flex-1 px-3 py-1.5 text-xs bg-error-500 text-white rounded-lg hover:bg-error-600 transition-colors"
              >
                删除
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

// ===== 主组件 =====

export function SessionHistory({
  sessions,
  currentSessionId,
  onOpenSession,
  onCreateSession,
  onDeleteSession,
  onLoadSessions,
}: SessionHistoryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/immutability
    loadSessions();
  }, []);

  const loadSessions = useCallback(async () => {
    setIsLoading(true);
    try {
      await onLoadSessions();
    } catch (error) {
      logger.error('加载会话列表失败:', error);
    } finally {
      setIsLoading(false);
    }
  }, [onLoadSessions]);

  const handleCreateSession = () => {
    const title = prompt('请输入新会话标题:', '新对话');
    if (title && title.trim()) {
      onCreateSession(title.trim());
    }
  };

  const filteredSessions = sessions.filter((session) => {
    if (!searchQuery.trim()) return true;
    const query = searchQuery.toLowerCase();
    return (
      session.title.toLowerCase().includes(query) || session.tags?.some((tag: any) => tag.toLowerCase().includes(query))
    );
  });

  return (
    <div className="h-full flex flex-col">
      {/* 头部区域 */}
      <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-neutral-800 dark:text-neutral-200 flex items-center gap-2">
            <FolderOpen className="w-5 h-5" />
            会话历史
          </h2>
          <button
            onClick={handleCreateSession}
            className="flex items-center gap-1 px-3 py-1.5 text-sm bg-primary-container text-primary-main rounded-lg hover:bg-primary-container transition-colors"
            title="创建新会话"
          >
            <Plus className="w-4 h-4" />
            新会话
          </button>
        </div>

        {/* 搜索框 */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="搜索会话..."
            className="w-full pl-10 pr-4 py-2 text-sm bg-neutral-100 dark:bg-neutral-700 border-none rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-neutral-800 dark:text-neutral-200 placeholder-neutral-400"
          />
        </div>
      </div>

      {/* 会话列表区域 */}
      <div className="flex-1 overflow-auto p-4 space-y-3">
        {isLoading && (
          <div className="flex items-center justify-center py-12">
            <div className="w-6 h-6 border-2 border-primary-500 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        {!isLoading && filteredSessions.length === 0 && (
          <div className="flex flex-col items-center justify-center py-12 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            <MessageSquare className="w-12 h-12 mb-3 opacity-50" />
            <p className="text-sm">暂无会话</p>
            <p className="text-xs mt-1">点击上方按钮创建新会话</p>
          </div>
        )}

        {!isLoading &&
          filteredSessions.map((session) => (
            <SessionCard
              key={session.id}
              session={session}
              isActive={currentSessionId === session.id.toString()}
              onClick={() => onOpenSession(session.id)}
              onDelete={() => onDeleteSession(session.id)}
            />
          ))}
      </div>

      {/* 底部统计 */}
      <div className="p-4 border-t border-neutral-200 dark:border-neutral-700">
        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">共 {sessions.length} 个会话</p>
      </div>
    </div>
  );
}

export default React.memo(SessionHistory);

/**
 * ChatMessages — 消息列表入口组件（薄层 v2.0）
 *
 * 所有逻辑已提取至 MessageList / MessageBubble / utils
 */
import React from 'react';
import MessageList from './MessageList';

import type { MessageListProps } from './MessageList'

// 导出新的拆分组件
export { MessageList } from './MessageList'
export { MessageBubble } from './MessageBubble'
export type { MessageListProps } from './MessageList'
export type { MessageBubbleProps } from './MessageBubble'

// 重新导出原有类型接口保持向后兼容
export type { MessageType } from './utils'
export { detectMessageType, parseChartData, renderMessageContent } from './utils'

// 导出 Props 类型别名（旧接口兼容）
// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ChatMessagesProps extends MessageListProps {}
export type { HistorySession } from './ChatHistory'
export { saveSessions, loadSessions, formatTime } from './ChatHistory'

// 导出子组件工具函数
export { LinkMessageCard, CodeMessageBlock, ImageMessageCard, FileMessageCard } from './utils'
export { tryExtractDomain, tryExtractTitle, extractExtension } from './utils'

export default function ChatMessages(props: ChatMessagesProps) {
  return <MessageList {...props} />
}

/**
 * CalloutBlock — 提示框区块
 *
 * 四种变体：
 * - info(蓝): 一般信息
 * - success(绿): 成功/正向结果
 * - warning(黄): 警告/注意
 * - summary(暖米): 摘要总结
 *
 * 配色体系与 MarkdownRenderer 保持一致
 */
import React, { useState, useCallback } from 'react'
import {
  Info, CheckCircle, AlertTriangle, FileText,
  ChevronDown, ChevronUp, Copy, Check,
} from 'lucide-react'
import type { CalloutData, CalloutVariant } from '../types'

interface CalloutBlockProps {
  data: CalloutData
}

const CALLOUT_STYLES: Record<string, {
  icon: typeof Info
  label: string
  containerClass: string
  iconColor: string
  titleColor: string
  textColor: string
  borderColor: string
}> = {
  info: {
    icon: Info,
    label: '信息',
    containerClass: 'bg-secondary-50 dark:bg-secondary-950/30',
    iconColor: 'text-secondary-500 dark:text-secondary-700',
    titleColor: 'text-secondary-700 dark:text-secondary-700',
    textColor: 'text-secondary-600/80 dark:text-secondary-700/80',
    borderColor: 'border-secondary-200 dark:border-secondary-800',
  },
  success: {
    icon: CheckCircle,
    label: '分析结果',
    containerClass: 'bg-primary-50 dark:bg-success-950/30',
    iconColor: 'text-primary-500 dark:text-primary-700',
    titleColor: 'text-primary-700 dark:text-primary-700',
    textColor: 'text-primary-700/80 dark:text-primary-700/80',
    borderColor: 'border-success-200 dark:border-success-800',
  },
  warning: {
    icon: AlertTriangle,
    label: '注意事项',
    containerClass: 'bg-warning-50 dark:bg-warning-950/30',
    iconColor: 'text-warning-500 dark:text-warning-700',
    titleColor: 'text-warning-700 dark:text-warning-700',
    textColor: 'text-warning-600/80 dark:text-warning-700/80',
    borderColor: 'border-warning-200 dark:border-warning-800',
  },
  summary: {
    icon: FileText,
    label: '总结',
    containerClass: 'bg-warning-50/60 dark:bg-warning-950/20',
    iconColor: 'text-warning-600 dark:text-warning-700',
    titleColor: 'text-warning-800 dark:text-warning-700',
    textColor: 'text-neutral-600 dark:text-neutral-400',
    borderColor: 'border-warning-200/80 dark:border-warning-800/60',
  },
}

function CalloutBlock({ data }: CalloutBlockProps) {
  // 兼容 style（LLM 常用）→ variant 字段映射
  const normalizedData: CalloutData = {
    ...data,
    variant: ((data as unknown) as Record<string, unknown>).variant as CalloutVariant || 'info',
  }
  const { variant = 'info', title, content, details } = normalizedData
  const [showDetails, setShowDetails] = useState(false)
  const [copied, setCopied] = useState(false)

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const handleCopy = useCallback(() => {
    navigator.clipboard.writeText(content).then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    })
  }, [content])

  const style = CALLOUT_STYLES[variant] || CALLOUT_STYLES.info
  const Icon = style.icon

  return (
    <div className={`mb-3 last:mb-0 rounded-lg border ${style.borderColor} ${style.containerClass} overflow-hidden`}>
      <div className="flex items-start gap-2 px-3 py-2">
        <Icon className={`flex-shrink-0 w-4 h-4 mt-0.5 ${style.iconColor}`} />
        <div className="min-w-0 flex-1">
          <div className="flex items-center justify-between gap-2">
            <div className={`text-xs font-semibold ${style.titleColor}`}>
              {title || style.label}
            </div>
            <button
              onClick={handleCopy}
              className="flex-shrink-0 p-1 rounded hover:bg-white dark:bg-neutral-900/20 transition-colors"
              title="复制内容"
            >
              {copied ? <Check className="w-3 h-3 text-success-500" /> : <Copy className="w-3 h-3 opacity-50 hover:opacity-100" />}
            </button>
          </div>
          <p className={`text-xs leading-relaxed mt-0.5 ${style.textColor}`}>
            {content}
          </p>
        </div>
      </div>

      {details && details.length > 0 && (
        <>
          <button
            onClick={() => setShowDetails(prev => !prev)}
            className="flex items-center gap-1 px-3 py-1.5 w-full text-left
              text-xs text-neutral-400 dark:text-neutral-400
              hover:bg-black/5 dark:hover:bg-white dark:bg-neutral-900/5 transition-colors"
          >
            {showDetails ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            <span>{showDetails ? '收起详情' : '查看详情'}</span>
          </button>
          {showDetails && (
            <div className="px-3 pb-2 space-y-1">
              {details.map((detail, i) => (
                <p key={i} className={`text-xs leading-relaxed pl-6 ${style.textColor} opacity-80`}>
                  • {detail}
                </p>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  )
}

